import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.D66Xq0Kv.js";const b=JSON.parse('{"title":"工具与技能","description":"","frontmatter":{},"headers":[],"relativePath":"智能体设计/工具与技能.md","filePath":"智能体设计/工具与技能.md","lastUpdated":null}'),o={name:"智能体设计/工具与技能.md"};function h(l,t,p,i,n,s){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="工具与技能" tabindex="-1">工具与技能 <a class="header-anchor" href="#工具与技能" aria-label="Permalink to &quot;工具与技能&quot;">​</a></h1><p>模型不碰磁盘、不发网络包、不驱动设备。它在一轮里只能做两件事：给出文字，或者点名一个宿主已经允许的动作。动作分两类：<strong>工具</strong>是宿主立刻能执行的能力；<strong>技能</strong>是教模型何时、按什么步骤去使用这些工具的说明。技能不是另一个进程，也不是一套新的插件运行时。</p><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h2><p>工具由宿主注册：名字、参数格式、一段给模型看的短说明。模型返回调用请求后，宿主校验参数、执行、把一段短结果送回模型。结果要短：成功或失败、关键标识、下一步需要的几行内容。完整日志留在宿主侧。</p><p>个人助手里常见的工具：</p><table tabindex="0"><thead><tr><th>工具</th><th>说明</th></tr></thead><tbody><tr><td>文件读写</td><td>读、写、修改工作区文件，按名字搜索文件内容</td></tr><tr><td>执行命令</td><td>在工作区里执行命令</td></tr><tr><td>搜索抓取</td><td>搜索和抓取网页</td></tr><tr><td>发消息</td><td>给当前用户发一条消息</td></tr><tr><td>定时任务</td><td>登记、列出、暂停、恢复、取消；登记只写持久存储，到点执行的是调度器</td></tr></tbody></table><p>接待和设备场景里还有另一类工具：表情、肢体、点单、下发一张图片。它们同样由宿主执行；模型输出的是标签或一份结构化决定，通道负责真正驱动设备。</p><p>工具名单在一轮开始时固定，模型不能在对话中安装新工具。需要新能力时，先在宿主里实现并加入允许名单，再让模型看得到。</p><p>有的运行时把发消息和任务登记做成模型可调用的外部工具，把文件和命令留给运行时自带的工具。两条路的分界相同：凡是要改变通道、日程或磁盘的事，都经过宿主的一次执行，模型只拿到执行后的文本。</p><h2 id="技能" tabindex="-1">技能 <a class="header-anchor" href="#技能" aria-label="Permalink to &quot;技能&quot;">​</a></h2><p>工具说明怎么用，往往比工具本身更长。如果把每个技能的步骤都放进系统提示词，每一轮都在重复发送用不上的规程，模型也更容易拿错步骤。</p><p>一份技能是一个目录，至少有一份说明：开头写名称和什么情况下应该使用，后面才是步骤、示例、可以调用的脚本路径。运行时在一轮开始时只把名称和适用时机放进上下文，并写明：判断用得上时，再用读文件的工具去读正文和同目录的其他文件。</p><p>模型的路径：</p><ol><li>从索引里看出「做某件事」有一份技能；</li><li>读那份说明；</li><li>按说明调用已经存在的工具。</li></ol><p>技能目录必须在这一轮的工作目录下面，否则模型看不见索引。换一套模型运行时，技能文件可以保持不变，只换「如何发现这个目录」的方式。</p><p>技能里需要本地程序时，正文写明调用工作区里的哪个脚本，由命令工具执行。不在技能里再启动一个长期服务，也不把技能做成需要单独安装的插件。</p><h2 id="领域技能" tabindex="-1">领域技能 <a class="header-anchor" href="#领域技能" aria-label="Permalink to &quot;领域技能&quot;">​</a></h2><p>有些能力比一份说明更重：点单、迎宾、按资料回答问题，都需要专用的处理步骤和一大份资料。这种技能注册成一组专用节点，外加一份可检索的资料库。资料按条目存放，并有一份索引；节点在本轮问题到来时检索，只把命中的条目放进这个节点的提示，手册全文不进入系统提示词，也不进入其他节点。</p><p>两种技能是同一原则的两种做法——步骤和资料留在外部，这一轮只拿用得上的那一截：</p><table tabindex="0"><thead><tr><th>维度</th><th>普通技能</th><th>领域技能</th></tr></thead><tbody><tr><td>检索执行者</td><td>模型自己读说明</td><td>节点内部，由运行时完成</td></tr><tr><td>资料形态</td><td>说明文件</td><td>条目化资料库 + 索引</td></tr><tr><td>模型职责</td><td>判断时机、读正文、调工具</td><td>决定怎么说、怎么用条目，不负责翻完整本手册</td></tr></tbody></table><p>规划节点如果存在，它只决定「要不要走进这个领域技能」，不读取资料正文。资料出现在执行该技能的那个节点里。</p><h2 id="权限" tabindex="-1">权限 <a class="header-anchor" href="#权限" aria-label="Permalink to &quot;权限&quot;">​</a></h2><p>工具让模型能够改文件、跑命令、对用户发消息。边界要放在宿主，不能放在提示词的劝告里。</p><table tabindex="0"><thead><tr><th>边界</th><th>规则</th></tr></thead><tbody><tr><td>触发权</td><td>只有有权的人能触发一轮工作：个人助手里是主人；接待设备上是已登记的那条连接</td></tr><tr><td>工作区</td><td>命令和文件限制在这块磁盘上的工作目录，技能索引也从这里发现；不堆放无关大文件，避免被整段拉进上下文</td></tr><tr><td>名单</td><td>允许名单之外的工具调用直接拒绝</td></tr><tr><td>投递</td><td>模型调发消息工具只表示「请把这段文字发给本轮所属的会话」，指定不了另一个通道的内部对象</td></tr><tr><td>场景</td><td>共享场合不加载只属于某一个人的技能资料，由场景注册表决定这一轮能看见哪些技能</td></tr></tbody></table><p>提示词可以提醒模型谨慎使用命令。真正挡住越权的是名单、目录和工作区，不是提醒本身。</p>',25)])])}const c=d(o,[["render",h]]);export{b as __pageData,c as default};
